import{_ as i,o as a,c as t,ae as o}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"ADR-0001: Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0001-architecture-overview.md","filePath":"adr/ADR-0001-architecture-overview.md"}'),s={name:"adr/ADR-0001-architecture-overview.md"};function r(n,e,l,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0001-architecture-overview" tabindex="-1">ADR-0001: Architecture Overview <a class="header-anchor" href="#adr-0001-architecture-overview" aria-label="Permalink to &quot;ADR-0001: Architecture Overview&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-07-09<br><strong>Deciders:</strong> HeliosBench Maintainers</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>HeliosBench is a Python-based CLI benchmark harness for evaluating LLM-powered CLI tools (primarily code generation agents). The project requires a clear architectural foundation to guide development, ensure extensibility, and document design rationale for contributors.</p><p>Key architectural concerns:</p><ol><li>How to structure the codebase for clarity and extensibility</li><li>How to execute benchmark tasks against external CLI binaries</li><li>How to collect and store resource utilization metrics</li><li>How to represent results for both human and machine consumption</li></ol><hr><h2 id="decision-1-python-cli-with-modular-monolith-structure" tabindex="-1">Decision 1: Python CLI with Modular Monolith Structure <a class="header-anchor" href="#decision-1-python-cli-with-modular-monolith-structure" aria-label="Permalink to &quot;Decision 1: Python CLI with Modular Monolith Structure&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Use a single Python package (<code>helios_bench</code>) with clearly separated modules for CLI, tasks, and core logic. No plugin system in Phase 1; extensibility is achieved through the task registry pattern.</p><h3 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>Python is the lingua franca of LLM tooling and CI/CD scripting</li><li>A single package avoids the overhead of namespace packages or microservice complexity for a focused CLI tool</li><li>The task registry pattern (<code>TASKS: dict[str, BenchmarkTask]</code>) provides a simple extension point</li><li><code>pyproject.toml</code> entry point (<code>helios-bench = &quot;helios_bench.cli:main&quot;</code>) provides standard Python distribution</li></ul><h3 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Simple setup, easy to install (<code>pip install -e .</code>), standard packaging</li><li>Positive: Single source of truth for task definitions in <code>tasks.py</code></li><li>Positive: Low barrier for new contributors</li><li>Negative: Adding a plugin system later would require refactoring the task registry</li><li>Negative: All tasks load into memory at import time</li></ul><hr><h2 id="decision-2-subprocess-based-task-execution" tabindex="-1">Decision 2: Subprocess-Based Task Execution <a class="header-anchor" href="#decision-2-subprocess-based-task-execution" aria-label="Permalink to &quot;Decision 2: Subprocess-Based Task Execution&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-1" tabindex="-1">Decision <a class="header-anchor" href="#decision-1" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Benchmark tasks are executed by spawning the target binary as a subprocess via <code>subprocess.Popen</code> with <code>shell=True</code>. The harness monitors the subprocess&#39;s resource usage through <code>psutil</code> and captures stdout/stderr.</p><h3 id="rationale-1" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-1" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>The harness tests external CLI tools; subprocess is the only viable isolation boundary</li><li><code>psutil</code> provides cross-platform process introspection (CPU, memory, file descriptors, threads)</li><li><code>shell=True</code> allows the benchmark to leverage existing shell environment (PATH, aliases)</li><li>Subprocess isolation prevents benchmark failures from crashing the harness</li></ul><h3 id="consequences-1" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-1" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Clean isolation between harness and target binary</li><li>Positive: Works with any CLI tool without modification</li><li>Positive: Resource monitoring is decoupled from benchmark execution</li><li>Negative: <code>shell=True</code> has security implications for untrusted binary paths</li><li>Negative: Cross-platform differences in process monitoring (e.g., <code>num_fds</code> not available on Windows)</li><li>Negative: Benchmark overhead includes subprocess spawn time</li></ul><hr><h2 id="decision-3-file-based-result-storage-with-json-yaml" tabindex="-1">Decision 3: File-Based Result Storage with JSON/YAML <a class="header-anchor" href="#decision-3-file-based-result-storage-with-json-yaml" aria-label="Permalink to &quot;Decision 3: File-Based Result Storage with JSON/YAML&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-2" tabindex="-1">Decision <a class="header-anchor" href="#decision-2" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Benchmark results are serialized as JSON (via <code>dataclasses.asdict</code> + <code>json.dump</code>) and optionally saved to files specified by the <code>--output</code> flag. No database layer is used in Phase 1.</p><h3 id="rationale-2" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-2" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>JSON is universally readable and scriptable (jq, Python, TypeScript)</li><li>No external database dependency keeps the tool lightweight</li><li>File-based storage makes results easy to archive, diff, and share</li><li>Users can choose to pipe output directly or save to files</li><li>YAML support via PyYAML is available for human-readable config (task definitions)</li></ul><h3 id="consequences-2" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-2" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Zero infrastructure required for result persistence</li><li>Positive: Results are trivially machine-parseable for CI/CD consumption</li><li>Positive: Easy to implement <code>--compare</code> mode by loading two result files</li><li>Negative: No query capability — all result analysis requires loading entire files</li><li>Negative: No built-in deduplication or incremental updates</li><li>Negative: Format changes require migration or backwards-compatibility logic</li></ul><hr><h2 id="decision-4-psutil-based-resource-monitoring" tabindex="-1">Decision 4: psutil-Based Resource Monitoring <a class="header-anchor" href="#decision-4-psutil-based-resource-monitoring" aria-label="Permalink to &quot;Decision 4: psutil-Based Resource Monitoring&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-3" tabindex="-1">Decision <a class="header-anchor" href="#decision-3" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Resource monitoring is implemented using the <code>psutil</code> library, with a dedicated <code>ResourceMonitor</code> class that runs a sampling thread alongside the benchmark subprocess. The <code>LeakDetector</code> class extends this with trend analysis across multiple runs.</p><h3 id="rationale-3" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-3" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li><code>psutil</code> is the de facto standard for cross-platform process monitoring in Python</li><li>Sampling in a separate thread provides non-blocking metric collection</li><li>Trend analysis using linear regression slope detects gradual resource leaks</li><li>The <code>aggregate()</code> method provides summary statistics from raw samples</li></ul><h3 id="consequences-3" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-3" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Comprehensive metrics (CPU, RSS, threads, file descriptors) from a single library</li><li>Positive: Thread-based sampling is lightweight and proven</li><li>Positive: Trend analysis catches gradual leaks that point-in-time checks miss</li><li>Negative: Sampling granularity is limited to <code>time.sleep(interval)</code> — no event-driven metrics</li><li>Negative: Thread join timeout (1.0s) may lose final samples on fast benchmarks</li><li>Negative: <code>psutil.cpu_percent(interval=0)</code> returns 0.0 on first call (documented behavior)</li></ul><hr><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>All four decisions are accepted and reflected in the current codebase. Future ADRs may supersede individual decisions as the project evolves.</p>',46)])])}const m=i(s,[["render",r]]);export{p as __pageData,m as default};
